  if(!advanced&&JSON.stringify(actualLineage)!==JSON.stringify(expectedLineage))throw Error('账户执行目标不匹配');if([CASH_SCOPE,MONTHLY_SCOPE].includes(a.target_scope)&&(!a.historical_target_quantities||!a.target_quantities||Object.values(a.historical_target_quantities).concat(Object.values(a.target_quantities)).some(q=>!Number.isSafeInteger(q)||q<0)))throw Error('账户目标无效');
