 async function read(url,options,handler){const token=++sequence;reading=true;if(proposal)proposalStale=true;render();let controlled=null;try{const r=await fetcher(url,{cache:'no-store',...options});const d=await r.json();if(token!==sequence)return;if(!r.ok){controlled=readFailure(d);if(['RESEARCH_SOURCE_WITHDRAWN','RESEARCH_SNAPSHOT_EXPIRED','MONTHLY_RESEARCH_ACCOUNT_CHANGED','CAPTURE_SUPERSEDED','RESELECT_REQUIRED'].includes(d.reason||d.error_code))clearProposal();throw Error('读取不可用');}handler(d);}catch(e){if(token===sequence){if(proposal)proposalStale=true;message=(controlled||'读取不可用，请稍后重新检查。')+(proposal?' 上次建议保留待刷新，旧报价不可采纳。':'');}}finally{if(token===sequence){reading=false;render();}}}
