 function rememberAccount(){knownAccount=account.account_id;knownAccountResearch=account.research_id;knownAccountDecision=account.capital_decision_id;knownInitialDecision=account.initial_capital_decision_id||account.capital_decision_id;knownInitialResearch=account.initial_research_id||account.research_id;knownLineage=lineage(account);knownMonth=account.target_month;storage.setItem(ACCOUNT_KEY,JSON.stringify({account_id:knownAccount,research_id:knownAccountResearch,decision_id:knownAccountDecision,initial_capital_decision_id:knownInitialDecision,initial_research_id:knownInitialResearch,target_month:knownMonth,...knownLineage}));}
